SELECT CASE WHEN channel IN ('partner', 'web') THEN 'tier_1' ELSE 'other' END AS channel_group, SUM(amount) AS total_amount, COUNT(*) AS cnt, ROUND(SUM(amount) * 100.0 / SUM(SUM(amount)) OVER (), 2) AS pct_of_total FROM orders GROUP BY CASE WHEN channel IN ('partner', 'web') THEN 'tier_1' ELSE 'other' END ORDER BY channel_group DESC;
